def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opp_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_opp_bids.append(float(bid))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    if not alive_opponents:
        base = DAILY_SALARY * (0.22 + 0.18 * scarcity)
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, round(base, 2))))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else highest_prev

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2
    if supply <= 17:
        danger += 2
    elif supply <= 19:
        danger += 1

    remaining_days = max(1, 10 - day + 1)
    reserve_target = DAILY_SALARY * 0.45 * remaining_days

    if danger >= 5:
        target = max(DAILY_SALARY * 0.92, urgent_prev + 2.5)
    elif danger >= 3:
        target = max(DAILY_SALARY * (0.72 + 0.12 * scarcity), highest_prev + 1.25)
    else:
        if supply >= 23 and hp >= 7 and no_water_days == 0:
            target = DAILY_SALARY * 0.28
        elif supply >= 20:
            target = DAILY_SALARY * (0.38 + 0.08 * scarcity)
        else:
            target = DAILY_SALARY * (0.5 + 0.12 * scarcity)
        if highest_prev > 0 and supply <= 18:
            target = max(target, highest_prev + 0.75)

    if budget < reserve_target and danger <= 2:
        target = min(target, DAILY_SALARY * 0.42)

    if hp <= 1 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.98)

    bid = max(0.0, min(float(budget), round(target, 2)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from each opponent's previous_trace for immediate reaction
    prev_bids = []
    prev_hp_after = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass
        if prev.get('hp_after', None) is not None:
            try:
                prev_hp_after.append(float(prev.get('hp_after')))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Estimate how tight water is: higher supply -> less need to overbid
    # supply is between 15..25; map to 0..1
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_tightness = 0.5
    else:
        supply_tightness = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_tightness < 0.0:
            supply_tightness = 0.0
        if supply_tightness > 1.0:
            supply_tightness = 1.0

    # Base bid: try to be competitive but not waste budget
    # Use yesterday's highest bid as a pressure indicator
    pressure_target = max(avg_prev_bid, highest_prev_bid * 0.92)

    # If my hp is low, conserve budget (bid lower) unless pressure is extreme
    if hp <= 2 or no_water_days >= 2:
        conservative_cap = DAILY_SALARY * (0.35 + 0.25 * (1.0 - supply_tightness))
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # Extreme pressure: still bid enough to secure water
            bid = max(conservative_cap, pressure_target)
        else:
            bid = min(pressure_target, conservative_cap)
    else:
        # Healthy: bid more when supply is tighter and pressure is high
        aggressive_floor = DAILY_SALARY * (0.45 + 0.25 * supply_tightness)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            bid = max(aggressive_floor, pressure_target)
        else:
            bid = max(aggressive_floor * 0.9, pressure_target * 0.9)

    # Also ensure we never exceed budget
    bid = float(bid)
    if bid > budget:
        bid = budget

    # If budget is very low, just go as low as possible while still having a chance
    # (simultaneous bids; small bid helps avoid immediate loss)
    min_reasonable = 5.0
    if budget < min_reasonable:
        return float(max(0.0, budget))

    if bid < min_reasonable:
        bid = min_reasonable

    # Small day-based wobble to avoid exact ties with opponents
    wobble = 1.0 + ((day % 5) - 2) * 0.02
    bid = bid * wobble

    if bid > budget:
        bid = budget
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0)

    remaining_days = EPISODE_DAYS - day_context['day']

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid_value = DAILY_SALARY * 0.5 

    # 1. Adjust based on my HP (urgency)
    if my_status['hp'] <= 2: 
        bid_value = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4: 
        bid_value = DAILY_SALARY * 0.85
    elif my_status['hp'] <= 6: 
        bid_value = DAILY_SALARY * 0.7

    # 2. Adjust based on opponent's previous highest bid (reaction)
    if highest_prev_bid > 0:
        if my_status['hp'] <= 4: 
            bid_value = max(bid_value, highest_prev_bid + 10)
        elif my_status['hp'] <= 6:
            bid_value = max(bid_value, highest_prev_bid + 5)
        else: 
            bid_value = max(bid_value, highest_prev_bid + 1)

    # 3. Adjust based on supply (competition pressure)
    if day_context['supply'] <= 18: 
        if my_status['hp'] <= 6: 
            bid_value = max(bid_value, DAILY_SALARY * 0.8)
        else: 
            bid_value = max(bid_value, DAILY_SALARY * 0.65)
    elif day_context['supply'] >= 22: 
        if my_status['hp'] > 6: 
            bid_value = min(bid_value, DAILY_SALARY * 0.4)
        else: 
            bid_value = min(bid_value, DAILY_SALARY * 0.6)

    # 4. Adjust for end-game or early-game
    if remaining_days <= 2: 
        if my_status['hp'] <= 6:
            bid_value = max(bid_value, DAILY_SALARY * 0.9) 
        else:
            bid_value = max(bid_value, DAILY_SALARY * 0.8) 
    elif day_context['day'] <= 2 and my_status['hp'] > 7: 
        bid_value = min(bid_value, DAILY_SALARY * 0.55)

    final_bid = min(my_status['budget'], bid_value)
    return max(1.0, final_bid)

